sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.summary-grid {
  margin-top: 20px;

  .stat-card {
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.06);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    color: #ffffff;

    &:hover {
      transform: translateY(-4px);
      box-shadow: 0 8px 25px rgba(0, 0, 0, 0.12);
    }

    &.stat-blue { background: linear-gradient(135deg, #2563eb, #1d4ed8); }
    &.stat-teal { background: linear-gradient(135deg, #0d9488, #0f766e); }
    &.stat-amber { background: linear-gradient(135deg, #d97706, #b45309); }

    .stat-icon {
      font-size: 32px;
      margin-right: 18px;
      opacity: 0.85;
    }

    .stat-content {
      flex: 1;

      .stat-heading {
        font-size: 15px;
        font-weight: 700;
        margin: 0 0 10px 0;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        opacity: 0.9;
      }

      .stat-metrics {
        display: flex;
        align-items: center;

        .metric {
          flex: 1;
          .val {
            font-size: 24px;
            font-weight: 800;
            display: block;
            line-height: 1;
          }
          .lbl {
            font-size: 11px;
            text-transform: uppercase;
            opacity: 0.8;
            font-weight: 600;
          }
        }

        .metric-divider {
          width: 1px;
          height: 28px;
          background: rgba(255, 255, 255, 0.25);
          margin: 0 12px;
        }
      }
    }
  }
}

sp_widget.script:
(function() {
    data.leave_pending = 0;
    data.leave_approved = 0;
    data.od_pending = 0;
    data.od_approved = 0;
    data.grievance_open = 0;
    data.grievance_resolved = 0;

    var stuGr = new GlideRecord('x_1983287_studen_0_student_profile');
    stuGr.addQuery('email', gs.getUser().getEmail());
    stuGr.query();

    var stuId = null;
    if (stuGr.next()) {
        stuId = stuGr.getUniqueValue();
    } else {
        // Fallback for Admin/Dev testing: find any student record
        var testGr = new GlideRecord('x_1983287_studen_0_student_profile');
        testGr.query();
        if (testGr.next()) {
            stuId = testGr.getUniqueValue();
        }
    }

    // 1. Leave Requests Aggregate
    var leaveCount = new GlideAggregate('x_1983287_studen_0_leave_request');
    if (stuId) leaveCount.addQuery('student', stuId);
    leaveCount.addAggregate('COUNT', 'status');
    leaveCount.groupBy('status');
    leaveCount.query();
    while (leaveCount.next()) {
        var lStatus = leaveCount.getValue('status');
        var lCnt = parseInt(leaveCount.getAggregate('COUNT', 'status'), 10);
        if (lStatus === 'Approved') data.leave_approved += lCnt;
        else if (lStatus === 'Submitted' || lStatus === 'Pending') data.leave_pending += lCnt;
    }

    // 2. OD Requests Aggregate
    var odCount = new GlideAggregate('x_1983287_studen_0_od_request');
    if (stuId) odCount.addQuery('student', stuId);
    odCount.addAggregate('COUNT', 'status');
    odCount.groupBy('status');
    odCount.query();
    while (odCount.next()) {
        var oStatus = odCount.getValue('status');
        var oCnt = parseInt(odCount.getAggregate('COUNT', 'status'), 10);
        if (oStatus === 'Approved') data.od_approved += oCnt;
        else if (oStatus === 'Submitted' || oStatus === 'Pending') data.od_pending += oCnt;
    }

    // 3. Grievance Aggregate
    var grvCount = new GlideAggregate('x_1983287_studen_0_grievance_request');
    if (stuId) grvCount.addQuery('student', stuId);
    grvCount.addAggregate('COUNT', 'status');
    grvCount.groupBy('status');
    grvCount.query();
    while (grvCount.next()) {
        var gStatus = grvCount.getValue('status');
        var gCnt = parseInt(grvCount.getAggregate('COUNT', 'status'), 10);
        if (gStatus === 'Resolved' || gStatus === 'Closed') data.grievance_resolved += gCnt;
        else data.grievance_open += gCnt;
    }
})();
